// Initialize195Agents constructs the full three-tier agent cohort.
func Initialize195Agents(vectorSize int) []Agent {
	agents := make([]Agent, 195)
	locales := []string{"US-EAST", "EU-CENTRAL", "AP-NORTHEAST", "SA-EAST"}

	// 64 Game Theory
	for i := 0; i < 64; i++ {
		locale := locales[i%len(locales)]
		agents[i] = NewGameTheoryAgent(fmt.Sprintf("game-theory-agent-%d", i), vectorSize, locale)
	}
	// 64 Human Design
	for i := 0; i < 64; i++ {
		locale := locales[i%len(locales)]
		agents[64+i] = NewHumanDesignAgent(fmt.Sprintf("human-design-agent-%d", i), vectorSize, locale)
	}
	// 67 General SEN
	for i := 0; i < 67; i++ {
		locale := locales[i%len(locales)]
		agents[128+i] = NewGeneralSENAgent(fmt.Sprintf("general-sen-agent-%d", i), vectorSize, locale)
	}

	return agents
}

// Helpers
func getRandomFloatValue() float64 {
	nBig, err := rand.Int(rand.Reader, big.NewInt(1000))
	if err != nil {
		return 0.0
	}
	return (float64(nBig.Int64()) / 1000.0) - 0.5
}

func getRandomIntValue() int64 {
	var b [8]byte
	_, _ = rand.Read(b[:])
	return int64(binary.BigEndian.Uint64(b[:]))
}
